-- ORACLE personality config (admin-editable, read by every client and by the nx-oracle Edge Function) +
-- per-account guided-tour state. Social/auth project (eisstodgncimypdawisy). Idempotent.

-- Per-permission admin access (main admin = owner implies all). Used by the admin panel milestone too.
create table if not exists public.nx_admin_perms (
  user_id uuid primary key references auth.users(id) on delete cascade,
  perms text[] not null default '{}',
  unlimited_gems boolean not null default false,
  granted_by uuid,
  updated_at timestamptz not null default now()
);
alter table public.nx_admin_perms enable row level security;
drop policy if exists nx_admin_perms_self on public.nx_admin_perms;
create policy nx_admin_perms_self on public.nx_admin_perms for select to authenticated using (user_id = auth.uid() or nx_is_owner());

create or replace function public.nx_has_perm(p text, u uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select u is not null and (
    nx_is_owner(u)
    or exists (select 1 from nx_admin_perms where user_id = u and (p = any(perms) or 'all' = any(perms)))
  )
$$;
revoke all on function public.nx_has_perm(text, uuid) from public, anon;
grant execute on function public.nx_has_perm(text, uuid) to authenticated, service_role;

create table if not exists public.nx_oracle_persona (
  id int primary key default 1 check (id = 1),
  data jsonb not null default '{}'::jsonb,
  version int not null default 0,
  updated_by uuid,
  updated_at timestamptz not null default now()
);
alter table public.nx_oracle_persona enable row level security;
drop policy if exists nx_oracle_persona_read on public.nx_oracle_persona;
create policy nx_oracle_persona_read on public.nx_oracle_persona for select using (true);
insert into public.nx_oracle_persona(id) values (1) on conflict do nothing;

-- Save (whole document). Only the owner or admins with the 'oracle' permission; every change is audited.
create or replace function public.nx_oracle_persona_save(p_data jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v int;
begin
  if not nx_has_perm('oracle') then raise exception 'forbidden'; end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' then raise exception 'bad config'; end if;
  if pg_column_size(p_data) > 512 * 1024 then raise exception 'config too large'; end if;
  update nx_oracle_persona set data = p_data, version = version + 1, updated_by = auth.uid(), updated_at = now()
   where id = 1 returning version into v;
  perform _nx_owner_log('oracle.persona.save', null, jsonb_build_object('version', v));
  return jsonb_build_object('ok', true, 'version', v);
end $$;
revoke all on function public.nx_oracle_persona_save(jsonb) from public, anon;
grant execute on function public.nx_oracle_persona_save(jsonb) to authenticated;

-- Guided tour: sections already seen, in its own column of the player's profile (the profile sync rewrites `data`).
alter table public.nx_profiles add column if not exists tour_seen text[] not null default '{}';
drop function if exists public.nx_tour_seen_set(text[], boolean);
create or replace function public.nx_tour_seen_set(p_sections text[], p_replace boolean default false) returns void
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'not signed in'; end if;
  if coalesce(array_length(p_sections, 1), 0) > 200 then raise exception 'too many'; end if;
  insert into nx_profiles(id) values (me) on conflict (id) do nothing;
  update nx_profiles set tour_seen = case when p_replace then coalesce(p_sections, '{}')
         else (select coalesce(array_agg(distinct x), '{}') from unnest(tour_seen || coalesce(p_sections, '{}')) x) end
   where id = me;
end $$;
revoke all on function public.nx_tour_seen_set(text[], boolean) from public, anon;
grant execute on function public.nx_tour_seen_set(text[], boolean) to authenticated;

-- Seed: the app's default persona config (only while the row is still empty; admins edit it afterwards).
