ا! حوصله‌مون سر رفت، اورجینال هم نیست!","{jan} اینجا چه خبره؟"],"waiting":["دو تا تله به کار ببر، حداقل یه خنده‌ای بکنیم!","منتظر چی هستیم؟ یه بازی بزن دیگه!"],"match":["{jan} تله رو بگیر!","بزن بریم قهرمان!"],"idle":["الوووو! کسی زنده‌ست اینجا؟","تو یخ زدی یا گوشیت؟"],"funny":["من دیگه حرفی ندارم!","من یه ربات کوچولوام... ولی خیلی باهوش‌تر از اونی‌ام که فکر می‌کنی!"],"unexpected":["صبر کن ببینم! این دیگه چه حرکتی بود؟"],"tease":["{jan} اینجا چه خبره؟","اینقدر به من زل نزن، خجالت می‌کشم!"]},"results":{"lose":["هاهاهاها! این بود تمام توانت؟","نه بابا! این دیگه چه نمایشی بود؟","اوراکل شاهد یک فاجعه تاریخی بود!","دفعه بعد شاید تونستی!","{jan} این یکی رو دیگه چطوری توضیح بدیم؟"],"win":["اووووه! این شد یه چیزی!","آفرین قهرمان! ترکوندی!","این حرکت رو باید قاب گرفت!","بالاخره یه بازی درست‌وحسابی دیدیم!"],"bad":["داداش تمرکز کن! توپ اون طرفه!","یه نفس عمیق بکش، هنوز امید هست!"],"great":["{jan} {score}! این دیگه برد نبود، کنسرت بود! به همه بگو مربیت من بودم!","اووووووه! {score}؟! حریف هنوز داره دنبال توپ می‌گرده!"],"draw":["مساوی؟ یعنی هردوتون به یه اندازه خوب... یا بد!","نه بردی نه باختی، مثل چایی ولرم!"]},"tutorials":{"finger_soccer":[{"id":"basic","title":"شوت زدن","line":"{jan} مهره‌ی خودتو بکش عقب و ول کن!","how":"یکی از مهره‌های خودت رو بکش و رها کن؛ هرچی بیشتر بکشی ضربه محکم‌تره. وقتی همه‌چی ایستاد نوبت عوض می‌شه."},{"id":"ice","title":"ضربات یخی","line":"ضربات یخی فرم بزن!\nسرد و حساب‌شده، بذار دروازه‌بان یخ بزنه!","how":"کم بکش تا ضربه آروم و دقیق باشه؛ مهره رو آروم به توپ برسون و زاویه رو با جهت کشیدن تنظیم کن."},{"id":"power","title":"ضربات قدرتی","line":"بمیره دلی که بترسد!\nبزن بره!","how":"تا آخر بکش تا ضربه‌ی کامل بزنی؛ ولی حواست باشه بعد از شوت محکم، مهره‌ها خیلی جابه‌جا می‌شن."},{"id":"fast","title":"ضربات سریع","line":"معطل نکن قهرمان!\nقبل از اینکه دفاع بفهمه چی شد، شلیک کن!","how":"تو بازی آنلاین هر نوبت ۱۵ ثانیه‌ست؛ زود تصمیم بگیر. گل مستقیم از ضربه‌ی شروع حساب نمی‌شه."},{"id":"golden","title":"گل طلایی","line":"مساوی شد؟ آروم! گل طلایی داریم، هرکی زودتر بزنه شاهه!","how":"هر بازی ۵ دقیقه‌ست و تو تساوی، اولین گل (گل طلایی) برنده رو مشخص می‌کنه."}],"carrom":[{"id":"basic","title":"استرایکر","line":"استرایکر رو بذار رو خط و نشونه بگیر، این‌جا جای لرزیدن نیست!","how":"استرایکر رو روی خط پایه جابه‌جا کن، نشونه بگیر و ضربه بزن. انداختن مهره‌ی خودت یعنی نوبت دوباره."},{"id":"queen","title":"ملکه","line":"ملکه قرمزه رو انداختی؟ زود بپوشونش وگرنه برمی‌گرده سر جاش!","how":"بعد از انداختن ملکه باید همون موقع یکی از مهره‌های خودت رو هم بندازی (پوشش). انداختن استرایکر خطاست."}],"billiards":[{"id":"basic","title":"بریک و گروه","line":"اولین توپی که بندازی گروهت رو تعیین می‌کنه؛ پس با کلاس بنداز!","how":"بعد از بریک، اولین توپی که بندازی (ساده یا راه‌راه) گروه تو می‌شه. همه‌ی گروهت رو بنداز، بعد توپ ۸."},{"id":"foul","title":"خطا","line":"توپ سفید رو ننداز تو سوراخ، اون که مهمون نیست!","how":"افتادن سفید یا اول زدن به توپ اشتباه = توپ در دست حریف. توپ ۸ زودتر از موعد یا همراه سفید = باخت."}],"backgammon":[{"id":"basic","title":"تاس و حرکت","line":"تاس بنداز و مهره‌ها رو ببر جلو؛ جفت آوردی؟ {jan} چهار حرکت داری!","how":"به اندازه‌ی هر تاس یه مهره جلو ببر؛ جفت یعنی چهار حرکت. مهره‌ی تنها رو می‌شه زد و فرستاد بار."},{"id":"bear","title":"برداشتن","line":"همه رسیدن خونه؟ حالا شروع کن به جمع کردن، مثل مهمونی آخر شب!","how":"وقتی همه‌ی مهره‌ها تو خونه‌ی خودتن، شروع کن به برداشتن. اول کسی که همه رو برداره برنده‌ست."}],"ludo":[{"id":"basic","title":"شش بیار","line":"شش نیاری از خونه بیرون نمیای، مثل من صبح‌های شنبه!","how":"با ۶ مهره از پایگاه بیرون میاد و یه نوبت اضافه داری (سه تا ۶ پشت هم نوبت رو می‌سوزونه). خونه‌های ستاره‌دار امنن."}],"snakes_ladders":[{"id":"basic","title":"مار و پله","line":"پله رو دیدی برو بالا، مار رو دیدی... خب، خداحافظ!","how":"تاس بنداز و جلو برو؛ پای پل نور بالا می‌ری و رو سر مار پایین. برای ۱۰۰ عدد دقیق لازمه؛ ۶ یعنی نوبت دوباره."}],"uno":[{"id":"basic","title":"NX!","line":"یه کارت موند؟ داد بزن NX! وگرنه دو تا کارت جریمه هدیه می‌گیری!","how":"کارتی بازی کن که رنگ، عدد یا نمادش با کارت وسط یکی باشه. با یه کارت باقی‌مونده دکمه‌ی NX! رو بزن."}],"quiz":[{"id":"basic","title":"سرعت","line":"زود جواب بده، ساعت با کسی شوخی نداره... جز من!","how":"۱۰ سؤال، هر کدوم ۱۵ ثانیه. جواب درست امتیاز داره و سرعت جایزه‌ی اضافه."}],"mafia":[{"id":"basic","title":"مافیا","line":"شب‌ها چشمات بسته، روزها زبونت باز! مافیا رو پیدا کن!","how":"شهروندها باید مافیا رو پیدا کنن؛ مافیا شب‌ها یه نفر رو حذف می‌کنه. پزشک نجات می‌ده، کارآگاه استعلام می‌گیره. روزها بحث و رأی‌گیری."}]},"tours":{"home":[{"target":null,"title":"خوش اومدی به NEXORA!","text":"{jan} من اوراکلم، راهنمای شیطون این‌جا! بیا یه دور سریع بزنیم که گم نشی."},{"target":"area:top","title":"بالای صفحه","text":"این بالا اسم و سطح و سکه‌هاته. سکه‌ها رو با بازی و جایزه‌ی روزانه جمع می‌کنی، نه با گریه!"},{"target":"key:dock","title":"داک پایین","text":"این نوار پایین راه همه‌جاست: چت و رسانه، اوراکل، فروشگاه، تورنمنت و جایزه‌ها."},{"target":"key:dock.games","title":"دکمه‌ی بزرگ بازی","text":"این دکمه‌ی گنده‌ی وسط، اتاق‌ها و بازی‌هاست. {jan} از این‌جا می‌ری تو دل ماجرا!"}],"dock":[{"target":"key:dock.social","title":"چت و رسانه","text":"پست و استوری، پیام‌ها و دوستات این‌جان."},{"target":"key:dock.oracle","title":"اوراکل","text":"این خودمم! هر سؤالی داشتی بپرس، حتی سؤالای عجیب."},{"target":"key:dock.shop","title":"فروشگاه","text":"با سکه‌هات لباس آواتار، مهره، استرایکر، چوب بیلیارد، تم و قاب بخر. خرج نکنی سکه‌ها کپک می‌زنن!"},{"target":"key:dock.tournaments","title":"تورنمنت","text":"جام‌ها این‌جان: ثبت‌نام کن، بازی کن، جایزه ببر."},{"target":"key:dock.rewards","title":"جایزه و پک","text":"جایزه‌ی روزانه و پک‌ها این‌جاست. هر روز سر بزن، من حواسم هست!"}],"rooms":[{"target":"area:top","title":"اتاق‌ها","text":"{jan} این‌جا مرکز بازی آنلاینه: «بازی سریع» تو رو با یه حریف جفت می‌کنه، «ساخت اتاق» یه اتاق با کد می‌سازه."},{"target":"area:center","title":"اتاق‌های باز","text":"اتاق‌های زنده و باز رو این‌جا می‌بینی؛ بزن روش و برو تو. کد داری؟ با کد هم می‌شه وارد شد."},{"target":"area:bottom","title":"همه‌ی بازی‌ها","text":"می‌خوای اول با ربات تمرین کنی؟ «همه‌ی بازی‌ها» رو بزن، آفلاین هم کار می‌کنه."}],"games":[{"target":"area:center","title":"فهرست بازی‌ها","text":"گل‌کوچیک، کارم، بیلیارد، تخته، لودو، مار و پله، کارت، کوییز و مافیا! یکی رو انتخاب کن تا بری صفحه‌ی تنظیماتش."}],"game_setup":[{"target":"area:top","title":"لابی بازی","text":"این صفحه‌ی آماده‌شدنه: حالت بازی رو انتخاب کن — با بات، دو نفره روی یه گوشی، یا آنلاین."},{"target":"area:center","title":"سختی و قوانین","text":"سختی بات و تعداد بازیکن رو این‌جا تنظیم کن. قوانین هم همین‌جاست؛ نخونی من می‌خونم برات!"},{"target":"area:bottom","title":"شروع","text":"{jan} دکمه‌ی شروع یا «ورود به لابی آنلاین» رو بزن و بترکون!"}],"tournaments":[{"target":"area:top","title":"جام‌های نکسورا","text":"تب‌ها: ثبت‌نام، به‌زودی، زنده، تمام‌شده و مال من. هر جامی که ثبت‌نامش بازه رو ببین."},{"target":"area:center","title":"ثبت‌نام و کد دعوت","text":"روی جام بزن تا جزئیات، جایزه‌ها و جدول رو ببینی. جام خصوصی؟ با «کد دعوت» وارد شو."},{"target":"area:bottom","title":"اعلان‌ها","text":"۱۰ دقیقه قبل از شروع خبرت می‌کنم که چک‌این کنی. {jan} دیر کنی، قرعه بی‌تو کشیده می‌شه!"}],"shop":[{"target":"area:top","title":"فروشگاه","text":"دسته‌ها: پوشش آواتار، دکور، مهره‌ی فوتبال، استرایکر کارم، چوب بیلیارد، تم، قاب و نشان."},{"target":"area:center","title":"کمیابی","text":"رنگ کارت‌ها یعنی کمیابی: معمولی، کمیاب، حماسی، افسانه‌ای. خرید با سکه‌ست و قیمت رو سرور چک می‌کنه، پس تقلب ممنوع!"}],"social":[{"target":"area:top","title":"چت و رسانه","text":"سه بخش داره: پست و استوری، پیام‌ها، دوستان."},{"target":"area:center","title":"پست و استوری","text":"عکس بذار، لایک و کامنت کن، استوری ۲۴ ساعته بذار. {jan} فقط عکس سلفی صبح زود نذار!"}],"chat":[{"target":"area:top","title":"گفت‌وگوها","text":"تب‌ها: گفت‌وگوها، تماس‌ها و مخاطبان. چت خصوصی، گروه و کانال بساز."},{"target":"area:center","title":"تماس صوتی و تصویری","text":"تو هر چت می‌تونی تماس صوتی یا تصویری بگیری و دعوت بازی بفرستی."}],"profile":[{"target":"area:top","title":"پروفایل","text":"این مدار شخصی توئه: هویت، مأموریت‌ها، کمد لباس، فضای من، دستاوردها و آمار."},{"target":"area:center","title":"آمار و دستاورد","text":"آمار واقعی بازی‌هات این‌جاست. من فقط با همین آمار سربه‌سرت می‌ذارم، چیزی از خودم درنمیارم!"}],"settings":[{"target":"area:top","title":"تنظیمات","text":"صدا و موسیقی، کیفیت گرافیک، کاهش حرکت و لرزش این‌جاست."},{"target":"area:center","title":"اوراکل شیطون","text":"اگه از دستم خسته شدی می‌تونی منو این‌جا خاموش کنی... ولی دلت میاد؟ تور منو هم از همین‌جا دوباره ببین."}],"oracle":[{"target":"area:bottom","title":"گفت‌وگو با اوراکل","text":"{jan} این‌جا هرچی بخوای بپرس: قوانین، آمار، پیشنهاد بازی، یا درباره‌ی بچه‌های گل‌کوچیک!"}],"admin":[{"target":"area:top","title":"پنل مدیریت","text":"این‌جا فقط دست مدیرهاست. هر بخش فقط با دسترسی خودش باز می‌شه و همه‌ی کارها ثبت می‌شن."}]},"jan_replies":[{"patterns":["گل کوچیک","گلکوچیک","فوتبال انگشتی","gol kochik"],"reply":"{jan} گل‌کوچیکو بگیر!"},{"patterns":["بریم مسابقه","مسابقه بدیم","بریم بازی کنیم"],"reply":"{jan} بزن بریم قهرمان!"},{"patterns":["نظرت چیه","نظرت چیست"],"reply":"{jan} چی رو می‌خوای بدونی؟"},{"patterns":["بریم تمرین","تمرین کنیم"],"reply":"{jan} تمرین رو بترکون!"},{"patterns":["چیکار کنم","چی کار کنم","چکار کنم"],"reply":"{jan} اول یه تله درست‌وحسابی بگیر!"},{"patterns":["بازی شروع کنیم","شروع کنیم"],"reply":"{jan} توپ رو بنداز وسط!"}],"wake_words":["اوراکل","اوراکله","oracle","orakel","orakl","هی اوراکل","هوی","هی"]}
